/* =====================================================================
   BAF736 Investment Banking — Extended question bank (authored)
   Grounded in the course textbook: Trần Tuấn Vinh & Hồ Công Hưởng (2023),
   Giáo trình Nghiệp vụ Ngân hàng Đầu tư — professional ethics (CFA Code),
   fundamental analysis and equity valuation, securities underwriting
   (private placement, IPO, rights issues), M&A, LBO capital structure,
   and secondary-market operations.
   level: 1 Know · 2 Understand · 3 Apply · 4 Analyze
   ===================================================================== */
window.QUIZ_BANK3 = [

{ id:"X1-01", ch:1, level:2, q:"Which statement best captures the <i>narrow</i> (classical) definition of investment banking?",
  opts:["Accepting deposits and making commercial loans","Underwriting securities — arranging the issuance of stocks and bonds by corporations","Managing assets on behalf of wealthy individuals","Operating the national payment system"],
  ans:1, expl:"Shiller's classical definition limits investment banking to the underwriting of securities. Broader definitions add M&A advisory, trading, asset management and principal investing.", src:"Ch.1 §1.1; [2] Ch.1" },

{ id:"X1-02", ch:1, level:2, q:"Under the US Standard Industrial Classification (SIC), investment banks are classified within which industry?",
  opts:["Industry 6211 — security brokers, dealers and flotation companies","Industry 6311 — life insurance","Industry 6021 — national commercial banks","Industry 6712 — bank holding companies"],
  ans:0, expl:"SIC 6211 covers establishments that buy, sell and broker securities and those \"generally known as investment bankers\" that originate, underwrite and distribute issues of securities; commodity brokers are a separate industry (6221).", src:"Ch.1 §1.1" },

{ id:"X1-03", ch:1, level:3, q:"An investment bank funds most of its balance sheet through repo, sell-and-buy-back and securities lending. This is best described as:",
  opts:["Unsecured borrowing","Equity capital","Secured borrowing — its largest funding source","Public deposits"],
  ans:2, expl:"Because it may not take public deposits, an investment bank's largest funding source is secured borrowing collateralised by liquid securities; unsecured borrowing (bank loans, bonds, commercial paper) is second.", src:"Ch.1 §1.1(c)" },

{ id:"X1-04", ch:1, level:3, q:"\"Use of funds determines funding\" describes the asset–liability management orientation of:",
  opts:["An insurance company","An investment bank","A central bank","A commercial bank"],
  ans:1, expl:"The investment bank raises funding only against actual investment needs — a liability-management orientation. The commercial bank raises deposits first and then deploys them (asset management orientation).", src:"Ch.1 §1.1(d)" },

{ id:"X1-05", ch:1, level:4, q:"Why do investment banks operate with structurally higher financial leverage than commercial banks?",
  opts:["They hold no risky assets","They are exempt from all capital regulation","Most of their assets are liquid and readily pledged as collateral","Their revenues are more stable"],
  ans:2, expl:"Liquid, pledgeable assets support high secured borrowing. Commercial banks hold more illiquid loans and are constrained by Basel capital-adequacy ratios.", src:"Ch.1 §1.1(e)" },

{ id:"X1-06", ch:1, level:2, q:"In Vietnam, the authority supervising investment-banking operations is:",
  opts:["The Ministry of Planning and Investment","The State Bank of Vietnam","The Government Inspectorate","The State Securities Commission (SSC)"],
  ans:3, expl:"Vietnam supervises securities activity through the SSC. In the US the SEC supervises, joined by the Federal Reserve after 2008; in Europe the central bank plays the leading role.", src:"Ch.1 §1.1(f), §1.5" },

{ id:"X1-07", ch:1, level:2, q:"Which is NOT one of the six functions of an investment bank identified in the course?",
  opts:["Monetary policy operator","Dealer and market maker","Trustee","Broker"],
  ans:0, expl:"The six functions are broker, dealer, market maker, trustee, advisor and servicer. Monetary policy is a central bank function.", src:"Ch.1 §1.3.2" },

{ id:"X1-08", ch:1, level:3, q:"An investment bank provides financing, clearing, custody and securities lending to a hedge fund. It is acting as:",
  opts:["Servicer (prime brokerage)","Trustee","Broker","Market maker"],
  ans:0, expl:"Prime brokerage is the servicer function: a bundle of financing, clearing, custody, securities lending and reporting services for hedge funds.", src:"Ch.1 §1.3.2(f)" },

{ id:"X1-09", ch:1, level:2, q:"Which entity is NOT currently among those performing investment-banking operations in Vietnam?",
  opts:["Securities investment companies operating at scale","Securities companies","Fund management companies","Partially universal banks"],
  ans:0, expl:"Securities investment companies are provided for in law but have not been established in practice; the operations are carried out by partially universal banks, securities companies and fund management companies.", src:"Ch.1 §1.4.2" },

{ id:"X1-10", ch:1, level:4, q:"Research analysts are pressured to publish favourable reports on a company the bank is underwriting. The primary control against this is:",
  opts:["Publishing fewer reports","Increasing the research budget","Allowing bankers to approve reports before release","An information barrier plus separation of research reporting lines and compensation from banking revenue"],
  ans:3, expl:"Research independence requires that analysts do not report to, and are not paid from, banking revenue, and that bankers cannot review reports pre-publication. The wall separates private-side from public-side staff.", src:"Ch.1 §1.4.4" },

{ id:"X1-11", ch:1, level:2, q:"The 'private side' of an investment bank consists of:",
  opts:["Investment-banking division staff who hold material non-public client information","External auditors","Research and trading staff","Back-office settlement staff"],
  ans:0, expl:"The private side holds inside information; the public side (research, sales and trading) must not receive it. The hard wall separates them.", src:"Ch.1 §1.4.4" },

{ id:"X1-12", ch:1, level:2, q:"Professional ethics matter in investment banking primarily because:",
  opts:["The business rests on client trust and on managing information asymmetry and conflicts","They are optional guidelines with no consequence","They only apply to junior staff","They replace the need for regulation"],
  ans:0, expl:"Investment banks hold privileged information and act for parties with conflicting interests. Ethical standards protect client trust, which is the franchise itself.", src:"[2] Ch.3 §3.1.2" },

{ id:"X1-13", ch:1, level:2, q:"Under the CFA Institute Code of Ethics, members must place which interests first?",
  opts:["The interests of the largest shareholder","Their own trading profits","Their employer's revenue targets","The integrity of the investment profession and the interests of clients, above their own"],
  ans:3, expl:"The Code requires members to place the integrity of the profession and the interests of clients above their own personal interests.", src:"[2] Ch.3 §3.3.1" },

{ id:"X1-14", ch:1, level:3, q:"An analyst learns of an unannounced acquisition from a banker and buys shares before the announcement. Which CFA standard is breached?",
  opts:["Standard on Record Retention","Standard on Material Nonpublic Information (insider trading)","Standard on Market Manipulation only","Standard on Referral Fees"],
  ans:1, expl:"Acting or causing others to act on material nonpublic information breaches the Integrity of Capital Markets standard. The information barrier exists to prevent exactly this.", src:"[2] Ch.3 §3.3.2" },

{ id:"X1-15", ch:1, level:3, q:"A manager allocates a hot IPO disproportionately to a favoured client. This most directly breaches the duty of:",
  opts:["Record retention","Independence from issuers","Diligence in research","Fair dealing with all clients"],
  ans:3, expl:"Fair dealing requires equitable treatment of all clients in investment actions and recommendations, including IPO allocation, under a written and applied allocation policy.", src:"[2] Ch.3 §3.3.2" },

{ id:"X1-16", ch:1, level:4, q:"Which best explains why investment-bank profitability is less stable than commercial-bank profitability?",
  opts:["Investment banks hold no capital","Fee and trading income depends on transaction volumes that collapse in downturns, while costs are largely fixed","Investment banks pay higher taxes","Commercial banks do not compete"],
  ans:1, expl:"Fees are earned per transaction. When confidence falls, issuance and M&A stop, but the largely fixed cost base — principally people — remains.", src:"Ch.1 §1.1, §1.5" },

{ id:"X1-17", ch:1, level:2, q:"Dodd-Frank (2010) requires US investment banks to, among other things:",
  opts:["Guarantee client returns","Convert into partnerships","Eliminate all trading activity","Support assets with at least 5% equity, hold higher liquidity and pass annual stress tests"],
  ans:3, expl:"Dodd-Frank imposed a minimum equity support for assets, much higher liquidity in readily saleable assets, and annual stress tests simulating a 2008-severity crisis.", src:"Ch.1 §1.2.3" },

{ id:"X1-18", ch:1, level:3, q:"A firm advises a seller on an M&A deal while simultaneously offering acquisition financing to bidders. This arrangement is:",
  opts:["Only possible for commercial banks","Prohibited in all jurisdictions","Free of any conflict","Staple financing — permitted but requiring disclosure and controls because of the conflict"],
  ans:3, expl:"Staple financing speeds the auction and earns a financing fee, but the bank advises the seller while lending to the buyer. It is managed with disclosure and separate teams.", src:"Ch.3 §3.4" },

{ id:"X1-19", ch:1, level:1, q:"Which of the following is the correct ordering of a bank's tiers from revenue-facing to processing?",
  opts:["Middle office → front office → back office","Front office → middle office → back office","Front office → back office → middle office","Back office → middle office → front office"],
  ans:1, expl:"Front office generates revenue and faces clients; middle office controls risk and compliance; back office settles, records and supports.", src:"Ch.1 §1.4.3" },

{ id:"X1-20", ch:1, level:4, q:"A bank's research division and its proprietary trading desk both cover the same stock. The key structural risk is that:",
  opts:["Research will be too slow","Research recommendations may be shaped to benefit the firm's own positions","Clients will receive too much information","Trading will stop entirely"],
  ans:1, expl:"This is the research–proprietary trading conflict. Controls include reporting-line separation, surveillance of trading around publication, and disclosure.", src:"Ch.1 §1.4.4" },

{ id:"X2-01", ch:2, level:2, q:"A private placement compared with a public offering generally involves:",
  opts:["No documentation at all","A limited number of professional or strategic investors and lighter disclosure, with transfer restrictions","Wider distribution and heavier disclosure","Mandatory listing immediately"],
  ans:1, expl:"Private placements target a limited set of qualified investors with reduced disclosure, but the securities carry transfer restrictions for a period.", src:"Ch.2 §2.2.2; [2] Ch.5 §5.3" },

{ id:"X2-02", ch:2, level:3, q:"Which is an advantage of private placement for the issuer?",
  opts:["Elimination of investor due diligence","Immediate liquidity for all shareholders","Speed, lower cost and confidentiality","Maximum possible price discovery"],
  ans:2, expl:"Private placements are faster, cheaper and confidential, but usually price below a public offering because investors demand an illiquidity discount.", src:"[2] Ch.5 §5.3.1" },

{ id:"X2-03", ch:2, level:2, q:"Under the Law on Securities 2019, the minimum paid-up charter capital for a joint-stock company to make a public offering of shares is:",
  opts:["VND 100 billion","VND 30 billion","VND 20 billion","VND 10 billion"],
  ans:1, expl:"The threshold is VND 30 billion by book value at the time of registration, together with profitability and ownership-dispersion conditions.", src:"Ch.2 §2.2.3" },

{ id:"X2-04", ch:2, level:2, q:"A public offering of shares in Vietnam generally requires the issuer to have been profitable for:",
  opts:["No profitability requirement applies","The most recent year only","Five consecutive years","The two preceding years, with no accumulated losses"],
  ans:3, expl:"The issuer must show profit in the two preceding years and no accumulated losses up to the year of registration.", src:"Ch.2 §2.2.3" },

{ id:"X2-05", ch:2, level:3, q:"Classifying an offering as 'fixed price', 'bookbuilding' or 'auction' is a classification by:",
  opts:["Target investor","Offering round","Pricing method","Distribution method"],
  ans:2, expl:"The four axes are: by offering round (IPO vs seasoned), by target investor (public, private, rights, ESOP), by pricing method (fixed price, bookbuilding, auction) and by distribution method (direct vs through an underwriter).", src:"Ch.2 §2.2.2" },

{ id:"X2-06", ch:2, level:3, q:"A company with 10 million shares trading at VND 60,000 makes a 1-for-4 rights issue at VND 40,000. The theoretical ex-rights price is:",
  opts:["VND 56,000","VND 60,000","VND 50,000","VND 44,000"],
  ans:0, expl:"TERP = (4×60,000 + 1×40,000) ÷ 5 = 280,000 ÷ 5 = VND 56,000.", src:"[2] Ch.5 §5.5.1" },

{ id:"X2-07", ch:2, level:3, q:"Using the previous data (cum-rights VND 60,000, TERP VND 56,000, 1-for-4), the theoretical value of one right is:",
  opts:["VND 2,000","VND 20,000","VND 16,000","VND 4,000"],
  ans:3, expl:"Value of a right = cum-rights price − TERP = 60,000 − 56,000 = VND 4,000. Equivalently (TERP − subscription price)/N = (56,000 − 40,000)/4 = 4,000.", src:"[2] Ch.5 §5.5.2" },

{ id:"X2-08", ch:2, level:4, q:"A shareholder who neither subscribes to a rights issue nor sells the rights will:",
  opts:["Be paid the subscription price in cash","Be unaffected because the rights are free","Suffer dilution and lose the value of the lapsed rights","Automatically receive the shares"],
  ans:2, expl:"The share price falls to TERP. A holder who does nothing is diluted and forfeits the value of the right — which is why rights are tradable.", src:"[2] Ch.5 §5.5" },

{ id:"X2-09", ch:2, level:2, q:"In a firm-commitment underwriting, the moment placement risk passes to the underwriter is:",
  opts:["When the prospectus is filed","At pricing, when the underwriting agreement is signed","On the first day of trading","At the end of the stabilisation period"],
  ans:1, expl:"The bank purchases the issue when the underwriting agreement is executed at pricing, and is left with any securities it cannot resell.", src:"Ch.2 §2.1" },

{ id:"X2-10", ch:2, level:3, q:"An issuer sells 20 million shares at $15 with a 5% gross spread and no greenshoe. Net proceeds are:",
  opts:["$300 million","$285 million","$270 million","$315 million"],
  ans:1, expl:"Gross = 20m × $15 = $300m; fee = 5% × 300 = $15m; net = $285m.", src:"Ch.2 §2.2.4" },

{ id:"X2-11", ch:2, level:3, q:"A greenshoe is exercised when, after listing, the share price:",
  opts:["Rises above the offer price","Is suspended","Falls below the offer price","Remains exactly at the offer price"],
  ans:0, expl:"If the price rises, underwriters exercise the option and take extra shares from the issuer at the offer price to cover their short. If the price falls they buy in the market instead, supporting the price.", src:"Ch.2 §2.2.4" },

{ id:"X2-12", ch:2, level:4, q:"Persistent IPO underpricing is best interpreted as:",
  opts:["Compensation to investors for valuation uncertainty, and a benefit to the underwriter's distribution clients — a conflict with the issuer","A pricing error that regulators eliminate","Evidence that issuers always overpay fees","Proof that markets are inefficient in the strong form"],
  ans:0, expl:"Underpricing reduces the underwriter's placement risk and rewards its investor clients, while costing the issuer 'money left on the table' — a structural conflict.", src:"Ch.2 §2.2.4" },

{ id:"X2-13", ch:2, level:2, q:"In debt capital markets, a bond is typically priced as:",
  opts:["The issuer's book value per share","A spread over a benchmark yield determined largely by the credit rating","A fixed percentage of the issuer's revenue","The average of peer share prices"],
  ans:1, expl:"The credit rating summarises default risk and sets the spread; adding it to the benchmark yield gives the coupon at issue.", src:"Ch.2 §2.3" },

{ id:"X2-14", ch:2, level:3, q:"A bond with a 9% coupon is trading at a price below par. This implies its yield to maturity is:",
  opts:["Equal to 9%","Below 9%","Above 9%","Indeterminable"],
  ans:2, expl:"A discount price means the required yield exceeds the coupon. At a premium, the yield is below the coupon; at par they are equal.", src:"Ch.2 §2.3" },

{ id:"X2-15", ch:2, level:2, q:"'Cov-lite' bond terms are best described as:",
  opts:["Bonds convertible into equity","Bonds with no coupon","Bonds guaranteed by the state","Debt with weakened covenant protection, shifting risk to lenders"],
  ans:3, expl:"Covenant-light structures reduce maintenance tests and restrictions, typically appearing in hot credit markets and shifting risk to lenders.", src:"Ch.2 §2.3" },

{ id:"X2-16", ch:2, level:2, q:"In a private-equity fund the party that commits the capital but does not manage it is the:",
  opts:["General partner","Limited partner","Custodian","Portfolio company"],
  ans:1, expl:"LPs commit capital and have limited liability; the GP sources, executes and manages the investments and earns fees plus carried interest.", src:"Ch.2 §2.4.1" },

{ id:"X2-17", ch:2, level:3, q:"A fund charges 20% carry over an 8% hurdle. Gross return is 6%. The carried interest earned is:",
  opts:["0%","0.4%","1.2%","20%"],
  ans:0, expl:"Return is below the hurdle, so no carry accrues. Only the management fee is charged.", src:"Ch.2 §2.4.5" },

{ id:"X2-18", ch:2, level:3, q:"A venture fund invests $8m for a 20% stake. The implied post-money valuation is:",
  opts:["$40 million","$32 million","$48 million","$1.6 million"],
  ans:0, expl:"Post-money = investment ÷ stake = 8 ÷ 0.20 = $40m; pre-money = $32m.", src:"Ch.2 §2.4.5" },

{ id:"X2-19", ch:2, level:4, q:"Why does venture capital rely on a small number of very large winners?",
  opts:["Most early-stage companies fail or return little, so portfolio returns are driven by outliers","Regulation caps the number of investments","VC funds may hold only one investment","Losses are reimbursed by the state"],
  ans:0, expl:"Early-stage failure rates are high and expected; the return distribution is highly skewed, so a few outsized outcomes must carry the fund.", src:"Ch.2 §2.4.5" },

{ id:"X2-20", ch:2, level:4, q:"Compared with a bought deal, a bookbuilt offering primarily gives the issuer:",
  opts:["Faster execution with no marketing","Freedom from underwriting fees","Better price discovery through observed investor demand, at the cost of time and disclosure","A guarantee of a higher price"],
  ans:2, expl:"Bookbuilding builds a demand curve before pricing. A bought deal is immediate and certain, but the bank prices in the risk it assumes.", src:"Ch.2 §2.1, §2.2.2" },

{ id:"X3-01", ch:3, level:2, q:"Two companies combine and both cease to exist, forming an entirely new company. This is:",
  opts:["An acquisition (mua lại)","A merger (sáp nhập)","A consolidation (hợp nhất)","A joint venture"],
  ans:2, expl:"In a consolidation all original companies cease to exist and a new entity is formed. In a merger the transferring company ceases to exist and the receiving company survives.", src:"Ch.3 §3.1.1" },

{ id:"X3-02", ch:3, level:3, q:"A buyer wishing to avoid unknown contingent liabilities of the target should prefer:",
  opts:["A share purchase","A tender offer","A stock-for-stock merger","An asset purchase"],
  ans:3, expl:"In an asset purchase the buyer takes only the liabilities it expressly assumes. In a share purchase all liabilities travel with the company.", src:"Ch.3 §3.1.1" },

{ id:"X3-03", ch:3, level:2, q:"Which is a seller motive rather than a buyer motive in M&A?",
  opts:["Eliminating a competitor","Vertical control of the supply chain","Succession where there is no capable heir or manager","Achieving cost synergies"],
  ans:2, expl:"Succession, liquidity, capturing a premium and inability to fund growth are seller motives. Synergies, scale, market access and vertical control are buyer motives.", src:"Ch.3 §3.1.2" },

{ id:"X3-04", ch:3, level:3, q:"An acquisition of a supplier by a manufacturer is best classified as:",
  opts:["Reverse merger","Vertical","Horizontal","Conglomerate"],
  ans:1, expl:"Vertical combinations move along the supply chain to secure supply or capture margin.", src:"Ch.3 §3.1.3" },

{ id:"X3-05", ch:3, level:2, q:"In a sell-side auction the document released only after a confidentiality agreement is signed is the:",
  opts:["Prospectus","Fairness opinion","Teaser","Confidential Information Memorandum (CIM)"],
  ans:3, expl:"The one-page anonymous teaser is sent first; the detailed CIM follows once an NDA is signed.", src:"Ch.3 §3.2.1" },

{ id:"X3-06", ch:3, level:2, q:"A fairness opinion issued by an investment bank states that:",
  opts:["The consideration is fair, from a financial point of view, to shareholders","Regulatory approval is guaranteed","The target will achieve its forecasts","The transaction is strategically wise"],
  ans:0, expl:"A fairness opinion addresses financial fairness of the consideration only. It supports the board's discharge of its fiduciary duty; it is not commercial advice.", src:"Ch.3 §3.2.3" },

{ id:"X3-07", ch:3, level:3, q:"A target's unaffected price is VND 25,000 and the offer is VND 32,500. The premium is:",
  opts:["7.5%","25%","23%","30%"],
  ans:3, expl:"Premium = 32,500 ÷ 25,000 − 1 = 30%.", src:"Ch.3 §3.3" },

{ id:"X3-08", ch:3, level:4, q:"An all-stock acquirer trades at a P/E of 12× and pays a P/E of 18× for the target, with no synergies. The deal will be:",
  opts:["Accretive","Dilutive","Exactly neutral","Impossible to determine"],
  ans:1, expl:"Paying a higher P/E than one's own in an all-stock deal issues cheap earnings for expensive ones, diluting EPS absent synergies.", src:"Ch.3 §3.3" },

{ id:"X3-09", ch:3, level:3, q:"Which synergy type do markets typically discount most heavily?",
  opts:["Headcount reduction in duplicated functions","Revenue synergies from cross-selling","Procurement savings from combined volume","Facility consolidation"],
  ans:1, expl:"Revenue synergies depend on customer behaviour and are hardest to deliver; cost synergies are largely within management's control.", src:"Ch.3 §3.3" },

{ id:"X3-10", ch:3, level:2, q:"Due diligence in an M&A transaction primarily aims to:",
  opts:["Replace the audit","Set the exchange's listing price","Advertise the target to investors","Verify assumptions and identify risks and liabilities before commitment"],
  ans:3, expl:"Due diligence covers commercial, financial, tax, legal, environmental, HR and IT matters, validating the basis of the price and shaping warranties and indemnities.", src:"Ch.3 §3.2.2; [2] Ch.6 §6.3.3" },

{ id:"X3-11", ch:3, level:3, q:"An earn-out in a purchase agreement is used mainly to:",
  opts:["Bridge a valuation gap by making part of the price contingent on future performance","Avoid regulatory approval","Guarantee the buyer a minimum return","Replace the need for due diligence"],
  ans:0, expl:"Earn-outs defer part of the consideration subject to agreed performance targets, bridging disagreement over value — at the cost of measurement disputes.", src:"Ch.3 §3.4.4" },

{ id:"X3-12", ch:3, level:2, q:"A bridge loan in acquisition financing is best described as:",
  opts:["Equity contributed by the sponsor","A loan to the target's customers","Permanent 30-year funding","Short-term funding giving certainty at signing, later refinanced into bonds or term loans"],
  ans:3, expl:"The bridge assures the seller funds are certain; it is deliberately priced to escalate so the borrower refinances promptly.", src:"Ch.3 §3.4" },

{ id:"X3-13", ch:3, level:2, q:"In a leveraged buyout, the debt is primarily serviced by:",
  opts:["The target company's own cash flows","The sponsor's other funds","Government guarantees","The investment bank's balance sheet"],
  ans:0, expl:"LBO debt is repaid from the acquired company's cash flow, which is why cash-flow stability is the first screening criterion.", src:"Ch.3 §3.4; [2] Ch.7 §7.1.1" },

{ id:"X3-14", ch:3, level:3, q:"Which target characteristic is LEAST attractive for an LBO?",
  opts:["Proven management team","High ongoing capital-expenditure requirements","Leading, defensible market position","Strong and predictable free cash flow"],
  ans:1, expl:"Heavy capex competes with debt service for cash. The textbook criteria favour strong cash flow, defensible position, growth opportunity, efficiency upside, low capex, solid asset base, proven management and undervaluation.", src:"[2] Ch.7 §7.3" },

{ id:"X3-15", ch:3, level:2, q:"In an LBO capital structure, which ranks most senior?",
  opts:["Mezzanine debt","High-yield bonds","Term Loan A (senior secured bank debt)","Sponsor equity"],
  ans:2, expl:"Priority runs senior secured bank debt (Term Loan A/B) → second lien → high-yield bonds → mezzanine/PIK → sponsor equity, with cost rising as seniority falls.", src:"[2] Ch.7 §7.4" },

{ id:"X3-16", ch:3, level:3, q:"Compared with Term Loan A, Term Loan B typically has:",
  opts:["Longer maturity, minimal amortisation and institutional investors as holders","No security over assets","A lower interest rate always","Shorter maturity and heavier amortisation"],
  ans:0, expl:"Term Loan A amortises and is held by banks; Term Loan B is longer-dated with nominal amortisation and a bullet repayment, held largely by institutional investors.", src:"[2] Ch.7 §7.4.2–7.4.3" },

{ id:"X3-17", ch:3, level:2, q:"Mezzanine debt in an LBO is characterised by:",
  opts:["First-priority security and the lowest cost","A government guarantee","Being senior to bank debt","Subordination, higher cost, and sometimes warrants or PIK interest"],
  ans:3, expl:"Mezzanine sits between senior debt and equity: subordinated, more expensive, and often carrying equity upside through warrants or PIK features.", src:"[2] Ch.7 §7.4.6" },

{ id:"X3-18", ch:3, level:4, q:"A sponsor achieves a 2.5× money multiple over 5 years. The approximate IRR is:",
  opts:["About 50%","About 20%","About 30%","About 12%"],
  ans:1, expl:"IRR = 2.5^(1/5) − 1 ≈ 1.201 − 1 ≈ 20%.", src:"Ch.3 §3.4; LBO lab" },

{ id:"X3-19", ch:3, level:4, q:"An LBO thesis relies mainly on exiting at a higher multiple than entry. This is concerning because:",
  opts:["Debt paydown is impossible","Regulators prohibit it","Multiples never change","Multiple expansion is a market bet rather than an operational achievement"],
  ans:3, expl:"Returns from deleveraging and EBITDA growth reflect execution; multiple expansion depends on market conditions at exit and is outside the sponsor's control.", src:"Ch.3 §3.4; LBO lab" },

{ id:"X3-20", ch:3, level:2, q:"A poison pill defends against a hostile bid by:",
  opts:["Delisting the company automatically","Selling the company to employees","Paying the bidder to withdraw","Allowing other shareholders to buy discounted shares once the bidder crosses a threshold, diluting it"],
  ans:3, expl:"The rights plan makes an unsolicited accumulation prohibitively dilutive, forcing the bidder to negotiate with the board.", src:"Ch.3 §3.5.2" },

{ id:"X3-21", ch:3, level:3, q:"A target facing a hostile bid invites a friendlier acquirer to make a competing offer. This tactic is:",
  opts:["Greenmail","Pac-Man","Crown jewel","White knight"],
  ans:3, expl:"A white knight is a preferred alternative bidder. Pac-Man is a counter-bid for the raider; crown jewel sells the most desired asset; greenmail repurchases the raider's stake at a premium.", src:"Ch.3 §3.5.2" },

{ id:"X3-22", ch:3, level:4, q:"Empirical research on staggered boards finds they are generally associated with:",
  opts:["Guaranteed bid success for hostile bidders","No measurable effect on takeover outcomes","A much higher likelihood that the target remains independent, so shareholders may forgo a premium","Lower legal costs for the bidder"],
  ans:2, expl:"Bebchuk and co-authors found that an effective staggered board nearly doubles the likelihood that a hostile target remains independent — the entrenchment risk. Poison pills, by contrast, are associated with higher premiums when a sale does happen.", src:"Ch.3 §3.5.2" },

{ id:"X3-23", ch:3, level:3, q:"Which is an alternative to M&A rather than a form of it?",
  opts:["Consolidation","Tender offer","Asset purchase","Strategic alliance"],
  ans:3, expl:"Joint ventures, strategic alliances, licensing and organic expansion are alternatives that avoid the premium and integration risk of a full combination.", src:"Ch.3 §3.5.3" },

{ id:"X3-24", ch:3, level:4, q:"The most common reason acquirers fail to create value is best summarised as:",
  opts:["Regulators block most deals","Overpayment combined with overestimated synergies and integration failure","Targets are always fraudulent","Financing is never available"],
  ans:1, expl:"The premium is paid at closing while synergies are deferred and uncertain; poor integration then prevents their realisation.", src:"Ch.3 §3.5.1" },

{ id:"X4-01", ch:4, level:2, q:"An open-end fund differs from a closed-end fund principally because it:",
  opts:["Never publishes a NAV","Has a fixed number of units","Cannot hold equities","Continuously issues and redeems units at NAV"],
  ans:3, expl:"Open-end funds issue and redeem at NAV, so size varies with flows and liquidity must be maintained. Closed-end funds have a fixed unit count traded on the secondary market.", src:"Ch.4 §4.1.2" },

{ id:"X4-02", ch:4, level:3, q:"A closed-end fund's market price may deviate from NAV because:",
  opts:["NAV is never calculated","Units are not transferable","There is no redemption mechanism to force convergence","Regulators fix the price"],
  ans:2, expl:"Without redemption at NAV, price is set by secondary-market supply and demand, so closed-end funds often trade at a discount or premium.", src:"Ch.4 §4.1.2" },

{ id:"X4-03", ch:4, level:3, q:"A fund holds assets of VND 2,400 billion and liabilities of VND 150 billion, with 90 million units outstanding. NAV per unit is:",
  opts:["VND 24,000","VND 26,667","VND 25,000","VND 16,667"],
  ans:2, expl:"NAV per unit = (2,400 − 150) ÷ 90 = 2,250 ÷ 90 = VND 25,000 (in thousands per unit terms as scaled).", src:"Ch.4 §4.2.3" },

{ id:"X4-04", ch:4, level:2, q:"The role of the supervisory bank (custodian) in a Vietnamese public fund is to:",
  opts:["Select the fund's investments","Hold the fund's assets independently and monitor compliance with the charter","Guarantee the fund's return","Set the management fee"],
  ans:1, expl:"Independent custody and supervision protect investors by separating asset safekeeping from investment decision-making.", src:"Ch.4 §4.2.3" },

{ id:"X4-05", ch:4, level:3, q:"A fund charges 1.5% management and 20% carry over a 10% hurdle. Gross return is 18%. Investor net return is:",
  opts:["13.9%","16.5%","15.5%","14.9%"],
  ans:3, expl:"Excess = 18 − 10 = 8%; carry = 20% × 8 = 1.6%; net = 18 − 1.5 − 1.6 = 14.9%.", src:"Ch.4 §4.2.3" },

{ id:"X4-06", ch:4, level:4, q:"A high-water mark exists principally to prevent:",
  opts:["Regulators auditing the fund","Investors redeeming early","The manager charging performance fees twice on the same recovered gains","The fund exceeding its benchmark"],
  ans:2, expl:"After a loss year, no carry may be charged until NAV exceeds the prior peak — otherwise volatility alone would generate fees.", src:"Ch.4 §4.2.3" },

{ id:"X4-07", ch:4, level:2, q:"Which measure evaluates active return per unit of tracking error?",
  opts:["Beta","Sharpe ratio","Expense ratio","Information ratio"],
  ans:3, expl:"IR = (R_P − R_B) ÷ tracking error isolates skill relative to a benchmark; Sharpe uses total risk and the risk-free rate.", src:"Ch.4 §4.3.2" },

{ id:"X4-08", ch:4, level:3, q:"A portfolio returns 14% with volatility of 16%; the risk-free rate is 5%. Its Sharpe ratio is:",
  opts:["0.31","0.56","0.88","1.14"],
  ans:1, expl:"Sharpe = (14 − 5) ÷ 16 = 0.5625 ≈ 0.56.", src:"Ch.4 §4.3.2" },

{ id:"X4-09", ch:4, level:2, q:"Which is NOT one of the characteristics of a good benchmark?",
  opts:["Chosen after the results are known","Appropriate to the manager's style","Unambiguous and investable","Specified in advance"],
  ans:0, expl:"A benchmark selected retrospectively can flatter any manager. It must be specified in advance, unambiguous, investable, measurable and style-appropriate.", src:"Ch.4 §4.3.2" },

{ id:"X4-10", ch:4, level:2, q:"In the portfolio management process, the investment policy statement belongs to which phase?",
  opts:["Liquidation","Planning","Execution","Feedback"],
  ans:1, expl:"Planning identifies objectives and constraints and records them in the IPS; execution allocates and selects; feedback monitors, rebalances and evaluates.", src:"Ch.4 §4.3.1" },

{ id:"X4-11", ch:4, level:4, q:"Empirically, the largest share of variation in a portfolio's returns over time is explained by:",
  opts:["Security selection","Trading costs","Strategic asset allocation","Market timing"],
  ans:2, expl:"Decades of research find the long-run allocation across asset classes dominates return variability, which is why it is decided first.", src:"Ch.4 §4.3.2" },

{ id:"X4-12", ch:4, level:2, q:"Risk capacity differs from risk tolerance in that capacity refers to:",
  opts:["The manager's preference","The client's financial ability to absorb losses","The benchmark's volatility","The client's willingness to take risk"],
  ans:1, expl:"Tolerance is psychological willingness; capacity is objective ability given wealth, horizon and obligations. Profiling must address both.", src:"Ch.4 §4.4.2" },

{ id:"X4-13", ch:4, level:3, q:"A wealth manager receives a commission from a product provider for placing clients in its fund. The essential requirement is:",
  opts:["The commission must be donated","Disclosure of the conflict and demonstrable suitability for the client","The commission need not be mentioned","The client must pay the commission directly"],
  ans:1, expl:"Suitability and disclosure are the sector's principal duties; undisclosed inducements are the classic mis-selling risk.", src:"Ch.4 §4.4.2" },

{ id:"X4-14", ch:4, level:2, q:"A single-family office is best described as:",
  opts:["An exchange-traded fund","A retail mutual fund","A full institutional wealth-management service dedicated to one family","A government pension scheme"],
  ans:2, expl:"Family offices deliver bespoke investment, tax, estate and administrative services for a single family (or several, in a multi-family office).", src:"Ch.4 §4.4.1" },

{ id:"X4-15", ch:4, level:4, q:"Why has the growth of passive investing compressed asset-management fee income?",
  opts:["Regulators capped active fees","Most active managers underperform after fees, so flows migrate to low-cost index products","Passive funds are legally cheaper","Passive funds pay investors to join"],
  ans:1, expl:"Persistent after-fee underperformance drives money to cheap index vehicles, forcing fee reductions across the industry.", src:"Ch.4 §4.2.3" },

{ id:"X4-16", ch:4, level:3, q:"An ETF's market price is kept close to NAV mainly by:",
  opts:["Authorised-participant arbitrage through in-kind creation and redemption","Daily trading halts","The fund manager buying units","Regulatory price controls"],
  ans:0, expl:"APs create or redeem baskets whenever price diverges from NAV, arbitraging the gap away.", src:"Ch.4 §4.2.3" },

{ id:"X5-01", ch:5, level:2, q:"PESTEL analysis is used in fundamental analysis to examine:",
  opts:["The bid-ask spread","The margin call price","The macro-environmental factors affecting an industry","A company's internal financial ratios"],
  ans:2, expl:"PESTEL covers Political, Economic, Social, Technological, Environmental and Legal factors — the external environment layer of industry analysis.", src:"[2] Ch.4 §4.3.4" },

{ id:"X5-02", ch:5, level:2, q:"In Porter's five forces, the threat that customers can force prices down reflects:",
  opts:["Bargaining power of suppliers","Bargaining power of buyers","Threat of new entrants","Threat of substitutes"],
  ans:1, expl:"The five forces are rivalry among existing competitors, threat of new entrants, threat of substitutes, bargaining power of buyers and of suppliers.", src:"[2] Ch.4 §4.3.5" },

{ id:"X5-03", ch:5, level:3, q:"An industry with high fixed costs, undifferentiated products and many similar-sized competitors will most likely display:",
  opts:["Strong supplier power","No threat of substitutes","Intense rivalry and pressure on margins","Low rivalry and high margins"],
  ans:2, expl:"These conditions intensify competitive rivalry, pushing prices toward marginal cost and compressing profitability.", src:"[2] Ch.4 §4.3.5" },

{ id:"X5-04", ch:5, level:2, q:"In the industry life cycle, an industry with rapid sales growth, heavy reinvestment and negative free cash flow is most likely in the:",
  opts:["Pioneering / growth stage","Mature stage","Decline stage","Consolidation-only stage"],
  ans:0, expl:"Early-stage industries grow quickly but consume cash. Mature industries generate stable free cash flow; declining ones shrink.", src:"[2] Ch.4 §4.3.6" },

{ id:"X5-05", ch:5, level:2, q:"SWOT analysis classifies Strengths and Weaknesses as:",
  opts:["Internal factors","Macroeconomic variables","External factors","Accounting adjustments"],
  ans:0, expl:"Strengths and weaknesses are internal to the firm; opportunities and threats are external.", src:"[2] Ch.4 §4.3.7" },

{ id:"X5-06", ch:5, level:2, q:"Expressing every income-statement line as a percentage of revenue is:",
  opts:["Vertical (common-size) analysis","Horizontal analysis","Sensitivity analysis","Ratio analysis"],
  ans:0, expl:"Vertical analysis common-sizes a statement to one base figure. Horizontal analysis compares the same line across periods to reveal trends.", src:"[2] Ch.4 §4.5.4–4.5.5" },

{ id:"X5-07", ch:5, level:3, q:"A company has net income of VND 180bn, revenue of VND 1,500bn and equity of VND 900bn. Its ROE is:",
  opts:["12%","20%","7.5%","15%"],
  ans:1, expl:"ROE = 180 ÷ 900 = 20%. Net margin is 12% and would combine with asset turnover and leverage in a DuPont decomposition.", src:"[2] Ch.4 §4.5.6" },

{ id:"X5-08", ch:5, level:3, q:"Under the DuPont decomposition, ROE equals net margin × asset turnover ×:",
  opts:["Equity multiplier (financial leverage)","Dividend payout","Effective tax rate","Interest coverage"],
  ans:0, expl:"ROE = (NI/Sales) × (Sales/Assets) × (Assets/Equity), separating profitability, efficiency and leverage.", src:"[2] Ch.4 §4.5.6" },

{ id:"X5-09", ch:5, level:3, q:"A stock pays a dividend of VND 2,000 next year, grows at 5% forever, and investors require 12%. Gordon growth value is:",
  opts:["VND 24,000","VND 28,571","VND 16,667","VND 40,000"],
  ans:1, expl:"P0 = D1 ÷ (r − g) = 2,000 ÷ (0.12 − 0.05) = 2,000 ÷ 0.07 = VND 28,571.", src:"[2] Ch.4 §4.8.4.2" },

{ id:"X5-10", ch:5, level:4, q:"The Gordon growth model becomes unusable when:",
  opts:["The company is listed","The growth rate approaches or exceeds the required return","Dividends are paid annually","The dividend is constant"],
  ans:1, expl:"As g → r the denominator approaches zero and value explodes; g must be below r and, economically, below long-run nominal GDP growth.", src:"[2] Ch.4 §4.8.4.2" },

{ id:"X5-11", ch:5, level:2, q:"Free cash flow to the firm (FCFF) should be discounted at:",
  opts:["The WACC","The cost of equity","The risk-free rate","The dividend growth rate"],
  ans:0, expl:"FCFF belongs to all capital providers and is discounted at WACC to give enterprise value. FCFE is discounted at the cost of equity to give equity value directly.", src:"[2] Ch.4 §4.8.4.3" },

{ id:"X5-12", ch:5, level:4, q:"In a typical DCF, the terminal value usually represents:",
  opts:["None of the value","Exactly half of total value","The majority — often 60–80% — of total value","Under 10% of total value"],
  ans:2, expl:"Because the explicit forecast is short relative to a perpetuity, most value sits in the terminal value — which is why the terminal growth assumption is so heavily negotiated.", src:"[2] Ch.4 §4.8.4.3; DCF tool" },

{ id:"X5-13", ch:5, level:2, q:"Asset-based valuation is most appropriate for:",
  opts:["A pre-revenue start-up","A company with only intangible assets","An asset-heavy company, a holding company, or one being liquidated","A fast-growing software company"],
  ans:2, expl:"Net asset value suits asset-intensive businesses, investment holding companies and liquidation scenarios, where earnings power is a poor guide to value.", src:"[2] Ch.4 §4.8.4.4" },

{ id:"X5-14", ch:5, level:3, q:"The residual income model values equity as book value plus the present value of:",
  opts:["Depreciation add-backs","All future dividends","Earnings in excess of a charge for the cost of equity capital","Revenue growth"],
  ans:2, expl:"Residual income = net income − (cost of equity × opening book value). Value = book value + PV of residual income.", src:"[2] Ch.4 §4.8.4.5" },

{ id:"X5-15", ch:5, level:3, q:"EBITDA is VND 500bn, the peer median EV/EBITDA is 7.5×, net debt is VND 1,200bn and there are 200m shares. Value per share is:",
  opts:["VND 12,750","VND 8,250","VND 18,750","VND 25,000"],
  ans:0, expl:"EV = 7.5 × 500 = 3,750bn; equity = 3,750 − 1,200 = 2,550bn; per share = 2,550,000m ÷ 200m = VND 12,750.", src:"Ch.5 §5.1.5" },

{ id:"X5-16", ch:5, level:4, q:"Two peers have identical operations but different leverage. Which multiple remains directly comparable?",
  opts:["Dividend yield","P/E","EV/EBITDA","P/B"],
  ans:2, expl:"EV/EBITDA is measured before financing costs and is capital-structure neutral. Equity multiples embed each firm's leverage.", src:"Ch.5 §5.1.5" },

{ id:"X5-17", ch:5, level:2, q:"Analysts use the median rather than the mean peer multiple mainly because:",
  opts:["Multiple distributions are right-skewed, so outliers distort the mean","Regulators require it","It is easier to compute","The median is always higher"],
  ans:0, expl:"Multiples are bounded below by zero and unbounded above; one depressed-earnings peer can drag the mean far from the typical company.", src:"Ch.5 §5.1.5" },

{ id:"X5-18", ch:5, level:2, q:"Which listing condition relates to ownership dispersion on Vietnamese exchanges?",
  opts:["ROE of at least 5%","At least 15% of voting shares held by at least 100 non-major shareholders","No overdue debts beyond one year","Charter capital of at least VND 30 billion"],
  ans:1, expl:"Dispersion requirements ensure a genuine free float and liquidity after listing.", src:"Ch.5 §5.1.2" },

{ id:"X5-19", ch:5, level:3, q:"In equitizing a state-owned enterprise, the most contested valuation item is typically:",
  opts:["Land-use rights","Trade payables","Short-term deposits","Inventory"],
  ans:0, expl:"Land-use rights are often the largest and least comparable value item; undervaluation transfers public wealth to private buyers and attracts scrutiny.", src:"Ch.5 §5.2.3" },

{ id:"X5-20", ch:5, level:2, q:"An equity carve-out differs from a spin-off because a carve-out:",
  opts:["Raises cash by selling a minority stake via IPO","Always liquidates the subsidiary","Requires no regulatory filing","Distributes shares free to existing holders"],
  ans:0, expl:"A carve-out raises cash while the parent retains control; a spin-off distributes subsidiary shares to existing shareholders and raises none.", src:"Ch.5 §5.3" },

{ id:"X5-21", ch:5, level:4, q:"Under trade-off theory, the optimal capital structure is reached where:",
  opts:["Debt is zero","The marginal tax benefit of debt equals the marginal expected cost of financial distress","Leverage is maximised","The dividend payout is highest"],
  ans:1, expl:"Adding debt lowers WACC through the tax shield until rising distress costs and required returns dominate. The optimum is lower for volatile, asset-light firms.", src:"Ch.5 §5.4.2" },

{ id:"X5-22", ch:5, level:3, q:"A firm has EBITDA of VND 400bn and net debt of VND 1,600bn. Its leverage ratio is:",
  opts:["0.25×","6.0×","4.0×","2.5×"],
  ans:2, expl:"Net debt ÷ EBITDA = 1,600 ÷ 400 = 4.0× — a leveraged, sub-investment-grade profile.", src:"Ch.5 §5.4.5" },

{ id:"X5-23", ch:5, level:2, q:"Pecking-order theory predicts firms prefer to finance investment first with:",
  opts:["Government grants","Internal funds, then debt, then equity last","New equity","Debt only"],
  ans:1, expl:"Because of asymmetric information, issuing equity signals overvaluation, so firms prefer retained earnings, then debt, and issue equity last.", src:"Ch.5 §5.4.2" },

{ id:"X5-24", ch:5, level:4, q:"A company with concentrated family control and heavy undisclosed related-party transactions will most likely face:",
  opts:["Exemption from disclosure","A valuation premium","A lower cost of equity","A governance discount reflecting expropriation risk"],
  ans:3, expl:"Investors price the risk that cash flows are diverted from minorities, lowering the multiple. Remedying governance is measurable value creation.", src:"Ch.5 §5.5.2" },

{ id:"X5-25", ch:5, level:2, q:"Sum-of-the-parts valuation is most useful when:",
  opts:["Only book value is available","A diversified group's divisions warrant different multiples","A company has a single homogeneous business","The company is pre-revenue"],
  ans:1, expl:"SOTP values each division on its own peer multiple and aggregates, revealing whether the group trades below the value of its parts.", src:"Ch.5 §5.3" },

{ id:"X6-01", ch:6, level:2, q:"In securities brokerage, the investment bank's risk exposure is best described as:",
  opts:["Credit risk on the issuer","Operational, settlement and compliance risk, but no market risk","Currency risk only","Full market risk on every trade"],
  ans:1, expl:"An agency broker never takes the other side, so it bears no market risk — only execution, settlement and conduct risk.", src:"Ch.6 §6.1.1" },

{ id:"X6-02", ch:6, level:2, q:"Orders on a continuous matching market are prioritised by:",
  opts:["Price first, then time","Random allocation","Time first, then price","Order size, then broker identity"],
  ans:0, expl:"Price priority is applied first — highest bid, lowest ask — then time priority among orders at the same price.", src:"Ch.6 §6.1.4" },

{ id:"X6-03", ch:6, level:3, q:"An investor wants certainty of execution and accepts whatever price results. The appropriate order is:",
  opts:["ATC","LO","MP / MTL market order","A stop order"],
  ans:2, expl:"A market order guarantees execution but not price; a limit order guarantees price but not execution.", src:"Ch.6 §6.1.4" },

{ id:"X6-04", ch:6, level:2, q:"An ATO order participates only in the:",
  opts:["Continuous session","Off-exchange market","Opening call auction","Closing call auction"],
  ans:2, expl:"ATO participates in the opening call auction and takes precedence over limit orders at the same price; ATC applies to the closing auction.", src:"Ch.6 §6.1.4" },

{ id:"X6-05", ch:6, level:2, q:"On a Vietnamese trading board, a price shown in purple indicates the:",
  opts:["Ceiling price","Reference price","Floor price","Previous close"],
  ans:0, expl:"Purple marks the ceiling, light blue the floor, yellow the reference price, green an increase and red a decrease.", src:"Ch.6 §6.2.1" },

{ id:"X6-06", ch:6, level:3, q:"A market maker quotes 45.00 / 45.30. Its gross profit per share on a completed round-trip is:",
  opts:["0.30","45.15","0.15","0.60"],
  ans:0, expl:"Buying at the bid (45.00) and selling at the ask (45.30) earns the full spread of 0.30 per share, before inventory losses and costs.", src:"Ch.6 §6.1.5" },

{ id:"X6-07", ch:6, level:4, q:"Adverse selection cost for a market maker arises because:",
  opts:["The exchange charges fees","Inventory is always hedged","Informed counterparties trade against the dealer just before prices move","Clients trade randomly"],
  ans:2, expl:"The dealer must quote to everyone but cannot identify informed traders, so it systematically loses on those trades — a cost the spread must cover.", src:"Ch.6 §6.1.5" },

{ id:"X6-08", ch:6, level:4, q:"A dealer accumulating an unwanted long inventory will typically:",
  opts:["Widen only the bid","Raise both bid and ask","Withdraw from the market permanently","Lower both bid and ask to discourage sellers and attract buyers"],
  ans:3, expl:"Quotes are skewed to manage inventory back toward neutral, not to forecast direction.", src:"Ch.6 §6.1.5" },

{ id:"X6-09", ch:6, level:2, q:"Which is a required condition for market-making activity?",
  opts:["Exclusive trading rights","No capital requirement","An obligation to quote two-sided prices within a maximum spread for a minimum size","A guarantee of profit"],
  ans:2, expl:"Market makers must maintain continuous two-sided quotes meeting spread, size and presence obligations, backed by minimum capital.", src:"Ch.6 §6.1.5" },

{ id:"X6-10", ch:6, level:2, q:"Proprietary trading is distinguished from market making principally by:",
  opts:["Intent — taking positions to express a view rather than to facilitate client flow","The settlement cycle","The exchange used","The instruments traded"],
  ans:0, expl:"Market makers hold inventory to serve client demand; prop desks take positions for their own account. Evidencing this distinction is the core Volcker compliance problem.", src:"Ch.6 §6.3.1" },

{ id:"X6-11", ch:6, level:2, q:"A fundamental requirement when a securities company conducts both brokerage and proprietary trading is that:",
  opts:["Both are handled by the same trader","Client orders are disclosed to the prop desk","Proprietary orders are executed first","Client orders take absolute priority over the firm's own orders"],
  ans:3, expl:"Client priority, separate accounts, systems and personnel prevent front-running and misuse of client order information.", src:"Ch.6 §6.3.3" },

{ id:"X6-12", ch:6, level:3, q:"A 1-day 99% VaR of VND 12 billion means:",
  opts:["Expected daily profit is VND 12bn","The portfolio is risk-free","On 99% of days the loss should not exceed VND 12bn, but tail losses may be far larger","Losses will never exceed VND 12bn"],
  ans:2, expl:"VaR gives a confidence threshold, not a maximum. It says nothing about the severity of losses beyond it — the central lesson of 2008.", src:"Ch.6 §6.3.4" },

{ id:"X6-13", ch:6, level:3, q:"An investor buys VND 800m of shares with 40% initial margin. The loan from the broker is:",
  opts:["VND 320 million","VND 480 million","VND 200 million","VND 800 million"],
  ans:1, expl:"Equity = 40% × 800 = VND 320m; the loan is the remainder, VND 480m. Leverage = 1 ÷ 0.40 = 2.5×.", src:"Ch.6 §6.4.1" },

{ id:"X6-14", ch:6, level:3, q:"Stock bought at VND 80,000 with 50% initial and 40% maintenance margin triggers a margin call at:",
  opts:["VND 40,000","VND 48,000","VND 64,000","VND 66,667"],
  ans:3, expl:"Call price = 80,000 × (1 − 0.50) ÷ (1 − 0.40) = 80,000 × 0.5 ÷ 0.6 = VND 66,667.", src:"Ch.6 §6.4.1" },

{ id:"X6-15", ch:6, level:4, q:"Raising the maintenance margin requirement, holding all else constant, will:",
  opts:["Lower the margin-call price","Eliminate the possibility of a call","Have no effect on the call price","Raise the margin-call price, triggering calls sooner"],
  ans:3, expl:"Call price = P × (1 − initial) ÷ (1 − maintenance). A higher maintenance margin shrinks the denominator, raising the call price.", src:"Ch.6 §6.4.1" },

{ id:"X6-16", ch:6, level:4, q:"Margin lending is described as pro-cyclical because:",
  opts:["Brokers lend more as prices fall","It is only available in bull markets","Interest rates fall when prices fall","Falling prices trigger calls and forced selling, which push prices lower and trigger further calls"],
  ans:3, expl:"The feedback loop can turn a correction into a crash, which is why regulators cap margin ratios and monitor aggregate margin balances.", src:"Ch.6 §6.4.1" },

{ id:"X6-17", ch:6, level:2, q:"In a short sale, the borrower's obligation to the lender of the securities includes:",
  opts:["Returning the shares plus a borrow fee and passing through any dividends","Nothing beyond returning the shares","Paying the full purchase price permanently","Guaranteeing a price rise"],
  ans:0, expl:"Profit = sale − repurchase − borrow fee − dividends passed through. Collateral must also be posted and maintained.", src:"Ch.6 §6.4.2" },

{ id:"X6-18", ch:6, level:3, q:"An investor shorts at VND 50,000 and covers at VND 42,000, paying VND 500 in fees. Profit per share is:",
  opts:["VND 8,000","VND 500","VND 8,500","VND 7,500"],
  ans:3, expl:"Profit = 50,000 − 42,000 − 500 = VND 7,500.", src:"Ch.6 §6.4.2" },

{ id:"X6-19", ch:6, level:4, q:"A short squeeze occurs when:",
  opts:["Rising prices force crowded short sellers to buy back simultaneously, pushing prices higher still","Prices fall sharply and shorts profit","Borrow fees fall to zero","Regulators ban short selling"],
  ans:0, expl:"Forced covering adds buying pressure to an already rising price, amplifying the move — aggravated if lenders recall shares.", src:"Ch.6 §6.4.2" },

{ id:"X6-20", ch:6, level:4, q:"The principal regulatory concern with naked short selling is that:",
  opts:["It always lowers prices permanently","It eliminates market liquidity","It is identical to margin lending","Selling without arranging a borrow risks settlement failure"],
  ans:3, expl:"Without a located borrow, the seller may be unable to deliver, creating settlement failures — hence locate/borrow requirements.", src:"Ch.6 §6.4.2" },

{ id:"X6-21", ch:6, level:2, q:"Which best describes the role of a market maker in overall market quality?",
  opts:["Increasing volatility to widen spreads","Providing liquidity and price continuity, absorbing temporary order imbalances","Guaranteeing investors a profit","Setting the reference price administratively"],
  ans:1, expl:"By quoting continuously, market makers narrow spreads, smooth imbalances and reduce volatility.", src:"Ch.6 §6.1.5" },

{ id:"X6-22", ch:6, level:3, q:"Electronic execution has compressed brokerage commissions, so brokers increasingly earn revenue from:",
  opts:["Government subsidies","Higher fixed commissions","Issuing their own shares","Margin lending, securities lending and value-added services"],
  ans:3, expl:"Financing and ancillary services have replaced commission as the main monetisation of the retail brokerage relationship.", src:"Ch.6 §6.2.2" },

];
